Task: Put the red cube into the red tray and the blue cube into the blue tray.

Skill code (numbered):
  1| # Complete skill module
  2| import math
  3| import numpy as np
  4| from collections import defaultdict
  5| 
  6| def run(robot):
  7|     """
  8|     Sort objects by colour: place each cube into the tray that shares its colour.
  9|     The function returns True when all cubes have been deposited (or when the
 10|     episode time budget is exhausted – the caller checks the return value).
 11|     """
 12|     # 1. Get a fresh perception of the scene
 13|     obs = robot.observe()
 14|     objects = obs["objects"]
 15|     fixtures = obs["fixtures"]
 16| 
 17|     # 2. Build colour → (object_name, fixture_name) mapping
 18|     colour_to_obj = {}
 19|     colour_to_fixture = {}
 20|     for name, data in objects.items():
 21|         colour_to_obj[data["color"]] = name
 22|     for name, data in fixtures.items():
 23|         colour_to_fixture[data["color"]] = name
 24| 
 25|     # 3. Process each colour that has both an object and a tray
 26|     for colour, obj_name in colour_to_obj.items():
 27|         if colour not in colour_to_fixture:
 28|             continue  # no matching tray, skip
 29|         tray_name = colour_to_fixture[colour]
 30| 
 31|         obj_pose = robot.get_pose(obj_name)
 32|         tray_pose = robot.get_pose(tray_name)
 33| 
 34|         # ------------------------------------------------------------------
 35|         # 3a. Move above the object to a safe height
 36|         # ------------------------------------------------------------------
 37|         approach_x = obj_pose["pos"][0]
 38|         approach_y = obj_pose["pos"][1]
 39|         approach_z = 0.025  # safe height ~2.5 cm above the table
 40| 
 41|         try:
 42|             robot.move_to(approach_x, approach_y, approach_z,
 43|                           yaw=None, speed=0.07)
 44|         except Exception:  # MotionError or any other unexpected exception
 45|             robot.log("move_to above object failed, aborting this object")
 46|             continue
 47| 
 48|         # ------------------------------------------------------------------
 49|         # 3b. Lower to the estimated grasp height and close the gripper
 50|         # ------------------------------------------------------------------
 51|         grasp_z = 0.028  # fingertip level ≈ centre of a 3 cm cube
 52|         try:
 53|             robot.move_to(approach_x, approach_y, grasp_z,
 54|                           yaw=obj_pose["yaw"], speed=0.07)
 55|         except Exception:
 56|             robot.log("move_to grasp height failed, aborting this object")
 57|             continue
 58| 
 59|         robot.grasp()                     # close fingers around the cube
 60|         if robot.holding() != obj_name:   # verify that the cube is really held
 61|             robot.log("grasp verification failed, retrying once")
 62|             # simple retry: lift a bit and try again once
 63|             robot.move_to(approach_x, approach_y, grasp_z + 0.01, speed=0.07)
 64|             robot.grasp()
 65|             if robot.holding() != obj_name:
 66|                 robot.log(f"grasp still failed for {obj_name}")
 67|                 continue
 68| 
 69|         # ------------------------------------------------------------------
 70|         # 3c. Move above the matching tray
 71|         # ------------------------------------------------------------------
 72|         tray_x, tray_y, tray_z = tray_pose["pos"]
 73|         release_z = 0.025  # same safe height above the tray
 74|         try:
 75|             robot.move_to(tray_x, tray_y, release_z,
 76|                           yaw=None, speed=0.07)
 77|         except Exception:
 78|             robot.log("move_to above tray failed, aborting this object")
 79|             continue
 80| 
 81|         # ------------------------------------------------------------------
 82|         # 3d. Lower to just above the table and release the cube
 83|         # ------------------------------------------------------------------
 84|         release_above_table = 0.015  # just above the tabletop
 85|         try:
 86|             robot.move_to(tray_x, tray_y, release_above_table,
 87|                           yaw=None, speed=0.07)
 88|         except Exception:
 89|             robot.log("final release move failed, aborting")
 90|             continue
 91| 
 92|         robot.release()                     # open fingers to drop the cube
 93|         robot.wait(0.3)                     # give time for the cube to settle
 94| 
 95|     # 4. All known cubes have been processed – signal success to the caller
 96|     return True

